# member pvros_tta12: model-lumpi-track/pvrcnnpp-ros-g1v3, checkpoint md5 66c1f05a2e602113dd011d96a22ec334
python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-ros-g1v3 --ckpt model-lumpi-track/pvrcnnpp-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pvrcnnpp-ros-g1v3/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out $OUT/predictions_pvros_tta12.json
