# member vrros4_tta: model-lumpi-track/voxelrcnn-ros-g1v4, checkpoint md5 5c061261f002f5e04eaec1d4704b937f
python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-ros-g1v4 --ckpt model-lumpi-track/voxelrcnn-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/voxelrcnn-ros-g1v4/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vrros4_tta.json
# member vrros_tta: model-lumpi-track/voxelrcnn-ros-g1v3, checkpoint md5 5415c1ceb113d8ca31fcac3ed2ba4a57
