python common/tools/route_predictions.py merge model-lumpi-track/routed-g22 --pred g1=$OUT/predictions_g1.json --pred g1_tta=$OUT/predictions_g1_tta.json --pred g1v3=$OUT/predictions_g1v3.json --pred pp4_tta=$OUT/predictions_pp4_tta.json --pred ppros4_tta=$OUT/predictions_ppros4_tta.json --pred ppros_tta=$OUT/predictions_ppros_tta.json --pred pvros4_tta=$OUT/predictions_pvros4_tta.json --pred pvros4d2_tta=$OUT/predictions_pvros4d2_tta.json --pred pvros6_tta12=$OUT/predictions_pvros6_tta12.json --pred pvros_tta12=$OUT/predictions_pvros_tta12.json --pred vrros=$OUT/predictions_vrros.json --pred vrros4_tta=$OUT/predictions_vrros4_tta.json --pred vrros_tta=$OUT/predictions_vrros_tta.json --pred vrrosf6_tta12=$OUT/predictions_vrrosf6_tta12.json --out $OUT/predictions.json
