# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/lumpi-track/pcdet/g1-v6/points" ]; then SYN=(--syn-split val --syn-list model-lumpi-track/routed-g22/submissions/2026-11-05_s9j/synthetic_ids.txt); else SYN=(--syn-zip model-lumpi-track/routed-g22/submissions/2026-11-05_s9j/lumpi_s9j_submission.zip --syn-list model-lumpi-track/routed-g22/submissions/2026-11-05_s9j/synthetic_ids.txt); fi
python common/tools/package_submission.py model-lumpi-track/routed-g22 --tag repro-s9j --pred $OUT/predictions.json --synthetic pcdet/g1-v6 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s9j' --reproduction
Z=model-lumpi-track/routed-g22/test/output/repro-s9j/submission.zip
python common/tools/check_submission.py --track lumpi $Z --official
python common/tools/reproduce_submission.py model-lumpi-track/routed-g22 --tag s9j --compare-zip $Z     # predictions and frames against the scored zip
